// Keep only the new text of the reply (drop quoted history/signature) before classifying.
return $input.all().map(({ json: m }) => {
  const full = String(m.text || m.textPlain || m.snippet || '');
  const clean = full.split(/\n>|\nOn .{5,200}wrote:|-----Original Message-----|\n_{5,}|\nFrom: .+\nSent: /)[0]
    .replace(/\n{3,}/g, '\n\n').trim().slice(0, 4000);
  const fromRaw = typeof m.from === 'string' ? m.from : (m.from?.value?.[0]?.address || m.from?.text || '');
  const email = (String(fromRaw).match(/[^<>\s"]+@[^<>\s"]+/) || [])[0] || null;
  return { json: { method: 'POST', path: '/internal/replies', idempotencyKey: `reply-${m.id}`,
    body: { workspaceId: $env.KLYRO_WORKSPACE_ID, threadId: m.threadId, contactEmail: email ? email.toLowerCase() : undefined,
            replyText: clean, subject: m.subject, providerMessageId: m.id } } };
});
